-- WhatsNew.lua: generated from CHANGELOG.md by the release (make_whatsnew.py; do not edit by hand).
-- Per version: v, date, items = { { s = "add"|"chg"|"fix", fr = { title, text }, en = { title, text } } }
local _, ns = ...
ns.WHATSNEW = {
  { v = "1.0.0-beta.135", date = "2026-11-18", items = {
    { s = "add", fr = { "GPS avec Shortest Path, tes portails de mage", "Shortest Path ne connaît pas les portails que tu ouvres toi-même (Rune des portails). Quand notre GPS trouve un trajet qui commence par ta téléportation ou ton portail et qui fait gagner au moins 2 minutes sur celui de Shortest Path, la flèche le propose avec le bouton pour le lancer et dit combien tu gagnes (« Plus rapide que le trajet de Shortest Path : ~25 min de moins »). Une fois arrivé, Shortest Path refait son trajet depuis là." }, en = { "GPS with Shortest Path's route", "A mage teleport or portal of ours that saves 2+ minutes is offered with its cast button." } },
  } },
  { v = "1.0.0-beta.134", date = "2026-11-18", items = {
    { s = "fix", fr = { "GPS avec Shortest Path, le bouton de la pierre de foyer", "Quand le trajet de Shortest Path commence par ta pierre de foyer, Rappel astral ou une téléportation de mage, notre flèche affiche maintenant le bouton pour la lancer, comme sur notre propre trajet. La ligne d'en dessous dit la suite (« Puis Walk to Grom'gol... »). Shortest Path ne donne pas le sort par son API : WL Helper le reconnaît au texte de l'étape." }, en = { "GPS with Shortest Path's route", "The Hearthstone, Astral Recall or a mage teleport gets our cast button." } },
  } },
  { v = "1.0.0-beta.133", date = "2026-11-18", items = {
    { s = "add", fr = { "Taille des fenêtres", "Un seul réglage pour la taille de toutes les fenêtres de WL Helper (le guide, le suivi, le Comptoir, les groupes, la guilde, les réglages), de 60 % à 150 %. Dans Options > Général, sous la langue (« Taille de toutes les fenêtres »), ou en commande : /wlh taille 90, /wlh taille +, /wlh taille - (10 % de plus ou de moins). Chaque fenêtre garde son coin haut-gauche à sa place. En combat, le changement attend la fin du combat. La flèche du GPS garde son propre réglage (page GPS)." }, en = { "Window size", "One setting for every WL Helper window, 60 % to 150 % (Options > General, or /wlh size 90 / + / -)." } },
  } },
  { v = "1.0.0-beta.132", date = "2026-11-18", items = {
    { s = "fix", fr = { "Guide, dans la zone c'est dans la zone", "Dans une zone de monstres aux apparitions espacées (les Sirènes Fouette-bile d'Azshara pour « Le corail des sirènes »), la flèche t'envoyait encore à l'apparition la plus proche, à 100 m, alors que tu étais au milieu. Dans la zone, la flèche dit maintenant que tu y es tant qu'une apparition est à moins de 120 m (avant : 40). Le bassin des larmes garde 40 m : son île au milieu n'a pas de monstre." }, en = { "Guide", "Inside a mob area, you are \"there\" within 120 yd of a spawn (was 40); the Pool of Tears' island keeps 40." } },
  } },
  { v = "1.0.0-beta.131", date = "2026-11-18", items = {
    { s = "chg", fr = { "GPS, une seule flèche avec Shortest Path", "Avec « Avec la flèche de WL Helper », la flèche de Shortest Path et ses étapes dans le suivi des objectifs se coupent toutes seules (dans ses réglages). Tes réglages reviennent quand tu enlèves l'option ou que tu choisis un autre GPS. Plus rien à couper à la main." }, en = { "GPS", "Shortest Path's own arrow and journey tracker are turned off while our arrow shows its route, and given back after." } },
  } },
  { v = "1.0.0-beta.130", date = "2026-11-18", items = {
    { s = "add", fr = { "GPS, le trajet de Shortest Path avec notre flèche", "Avec « Envoyer les destinations à Shortest Path », la nouvelle option « Avec la flèche de WL Helper » (activée par défaut) garde notre flèche. Shortest Path calcule le trajet ; notre flèche vise son prochain point et dit son étape en cours, puis la suivante, les étapes d'après, la destination et le temps restant. Pour n'avoir que notre flèche, coupe celle de Shortest Path et son suivi de trajet dans ses propres réglages (Interface : la flèche ; Guidance : les étapes dans le suivi des objectifs). Option coupée : l'interface de Shortest Path, comme avant." }, en = { "GPS", "Shortest Path's route shown by WL Helper's arrow (new option, on by default)." } },
  } },
  { v = "1.0.0-beta.129", date = "2026-11-18", items = {
    { s = "add", fr = { "GPS, retour au cadavre", "Mort et libéré (fantôme), la flèche t'emmène à ton cadavre (« Ton cadavre »). Une fois ressuscité, elle reprend l'étape du guide ou le trajet que tu suivais. Ça marche aussi après un /reload en fantôme." }, en = { "GPS", "As a ghost, the arrow takes you to your corpse, then back to the step or trip you followed." } },
  } },
  { v = "1.0.0-beta.128", date = "2026-11-18", items = {
    { s = "fix", fr = { "GPS, la tour de l'archimage Xylem (Azshara)", "Aucun chemin ne monte en haut de sa tour, et la flèche partait dans les falaises. Elle t'envoie maintenant à Sanath Lim-yo, au pied de la tour (28.1, 50.1) : parle-lui, il te téléporte en haut. Une fois en haut, la flèche passe à Xylem. Les étapes des quêtes de mage de Xylem le disent aussi." }, en = { "GPS", "Archmage Xylem's tower has no path up: the arrow goes to Sanath Lim-yo at its foot, who teleports you up." } },
  } },
  { v = "1.0.0-beta.127", date = "2026-11-18", items = {
    { s = "add", fr = { "GPS, choisir entre Shortest Path et WL Helper", "Si Shortest Path est installé, une fenêtre demande une seule fois quel GPS suivre. « Shortest Path » : il prend tes destinations (son trajet sur la carte, ses vols, ses bateaux avec leurs départs, sa flèche) et notre flèche s'efface. « WL Helper » : notre GPS, comme avant. Le choix se change dans Options > GPS (« Envoyer les destinations à Shortest Path »), et le trajet en cours passe tout de suite à celui choisi." }, en = { "GPS", "With Shortest Path installed, asked once which GPS to follow; switching moves the trip under way at once." } },
  } },
  { v = "1.0.0-beta.126", date = "2026-11-18", items = {
    { s = "chg", fr = { "GPS, moins de bateaux et de zeppelins à la chaîne", "Pour choisir le trajet, chaque bateau ou zeppelin compte 2 minutes de plus que son temps (l'écran de chargement, le quai à trouver, le départ raté), le deuxième 4 minutes, le troisième 6. Un vol de 10 minutes passe donc avant « bateau pour Ratchet, vol jusqu'à Orgrimmar, zeppelin pour Fossoyeuse » s'il ne fait pas gagner nettement plus. Les temps affichés restent les vrais. Exemple : d'Orgrimmar vers les Terres ingrates, l'autre trajet proposé était « zeppelin pour Fossoyeuse, puis zeppelin pour Grom'gol, puis vol » pour gagner 30 secondes ; c'est maintenant un seul zeppelin, puis le vol." }, en = { "GPS", "Each boat or zeppelin weighs 2 more minutes in the choice (the 2nd 4, the 3rd 6): no ship chains for a few minutes saved." } },
    { s = "add", fr = { "GPS, la destination finale sur la flèche", "Tant que l'étape en cours est un vol, un bateau ou le chemin vers un quai, la flèche dit en haut, en doré, où tout ça mène : « Destination : Moulin-de-Tarren, Contreforts de Hautebrande ~12 min »." }, en = { "GPS", "The arrow tells the trip's final destination on top, with the time left." } },
  } },
  { v = "1.0.0-beta.125", date = "2026-11-18", items = {
    { s = "add", fr = { "Trouver un groupe, le choix en cartes", "Le bouton « Donjons » ouvre une fenêtre de grandes cartes, comme le choix du guide : l'image de chaque donjon, son nom, ses niveaux, « Ta route » et « Tes quêtes : N » quand tu as ses quêtes. Clic sur une carte : cochée (bord rouge et coche), re-clic : décochée. Trois onglets : Donjons, Raids, Quêtes et zones. Un donjon absent de la recherche de groupe du jeu est grisé. En bas, combien sont choisis, « Effacer » et « Chercher »." }, en = { "Find a group", "Dungeons, raids and questing zones picked on big cards with the dungeons' pictures, like the guide's." } },
    { s = "add", fr = { "Trouver un groupe, les quêtes de groupe", "Une quête élite ou de groupe de ton journal (ex. Summoning Shadra dans les Hinterlands) ajoute la source « Tes quêtes de groupe » : elle cherche les groupes de sa zone dans la recherche de groupe du jeu, et « Copier le texte de l'annonce » donne « Quête : Summoning Shadra (The Hinterlands), on cherche du monde ». Dans l'onglet Quêtes et zones, la zone de ta quête le dit. L'annonce elle-même se crée dans la recherche de groupe du jeu : le jeu ne laisse pas un addon la créer." }, en = { "Find a group", "Your group quests (elite) as a source: their zone searched, the listing text ready." } },
  } },
  { v = "1.0.0-beta.124", date = "2026-11-18", items = {
    { s = "add", fr = { "GPS, les portails du mage", "Un portail que tu sais ouvrir (Orgrimmar, Fossoyeuse, Les Pitons-du-Tonnerre ; Hurlevent, Forgefer, Darnassus côté Alliance) compte comme une téléportation quand tu as une Rune des portails : ouvre-le et prends-le. La flèche le lance comme une téléportation." }, en = { "GPS", "A mage's own portals count as teleports when a Rune of Portals is in the bags." } },
    { s = "add", fr = { "GPS, la rune qui manque", "Quand tu connais une téléportation ou un portail mais n'as pas la rune, le trajet s'en passe ; la carte du guide dit maintenant ce qu'elle ferait gagner (« Avec une Rune de téléportation : Téléport : Fossoyeuse (~8 min de moins) »). Avant, la téléportation disparaissait sans un mot." }, en = { "GPS", "When a missing rune leaves a teleport out, the card says how much time it would save." } },
  } },
  { v = "1.0.0-beta.123", date = "2026-11-18", items = {
    { s = "add", fr = { "GPS, envoyer les destinations à Shortest Path", "Si Shortest Path Forever est installé, Réglages > GPS > « Envoyer les destinations à Shortest Path ». Les étapes du guide, les repères de la carte (livres de Naowh, Ctrl-clic) et /way passent alors par lui : son trajet tracé sur la carte, les vols, les bateaux et zeppelins avec le compte à rebours du départ, les portails, et sa flèche. La flèche de WL Helper et son chemin se cachent pendant ce temps. Éteint par défaut ; si Shortest Path ne peut pas prendre le point (encore en chargement), le GPS de WL Helper guide." }, en = { "GPS", "Send destinations to Shortest Path Forever (its map route, flights, boats with departure timers), Settings > GPS." } },
  } },
  { v = "1.0.0-beta.122", date = "2026-11-18", items = {
    { s = "chg", fr = { "Petit suivi lisible", "Le bouton « − » du guide passe au petit suivi (l'action en cours, ses objectifs avec leur barre, les deux actions suivantes) à la place de la ligne unique d'avant. Textes plus grands (action en 14, objectifs en 13) et cadre un peu plus large. Clic sur le suivi : le guide complet revient." }, en = { "The guide's \"−\" switches to the small tracker (bigger text, objective bars); click it to get the whole guide back.", "" } },
    { s = "fix", fr = { "Classement PvP de la guilde, les doublons", "Chaque membre n'apparaît plus qu'une fois. Sur Forever, un personnage a un nom de famille (« Alandir Sheeplover ») : les anciennes copies le gardaient sous le prénom seul, les nouvelles sous le prénom et le nom, et ta propre ligne restait sous ton prénom. Les deux sont fusionnées (les chiffres les plus récents gardés) ; deux membres du même prénom restent séparés." }, en = { "Guild PvP ranking", "No more members listed twice (Forever surnames)." } },
    { s = "fix", fr = { "GPS, dans la zone d'un objectif", "Quand tu es déjà dans la zone pointillée, près des mobs (moins de 40 mètres), la flèche ne t'envoie plus au bord de la zone : le point, c'est toi, et il te suit. Loin de tout mob (une île au milieu de la zone) ou hors de la zone, elle t'emmène au mob le plus proche, comme avant." }, en = { "GPS", "Inside an objective's area, the arrow no longer sends you to its edge." } },
  } },
  { v = "1.0.0-beta.121", date = "2026-11-18", items = {
    { s = "chg", fr = { "Guide, la route suit ta position", "Toutes les 5 secondes, si tu es à plus de 400 mètres de l'endroit d'où la route a été calculée, les étapes restantes sont remises dans l'ordre depuis là où tu es (toujours en respectant l'ordre obligatoire des quêtes, puis le chemin le plus court). Ça couvre la pierre de foyer, un portail, un bateau ou une longue course dans la même zone, qui ne déclenchaient rien. Pas en combat, pas en vol, pas en donjon ; pas à chaque pas, pour que la flèche ne saute pas d'une étape à l'autre." }, en = { "The guide re-orders the steps left from where you are once you are 400 yards from where the route was planned (hearthstone, portal, boat, long ride).", "" } },
  } },
}
